def transform(grid):
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(markers) < 2:
        return grid

    pattern = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 5)]

    def nearest_distance(marker):
        r, c = marker
        return min(abs(r - y) + abs(c - x) for y, x, _ in pattern)

    source = min(markers, key=nearest_distance)
    target = next(m for m in markers if m != source)
    sr, sc = source
    tr, tc = target

    out = [row[:] for row in grid]
    out[tr][tc] = 0
    for r, c, color in pattern:
        y, x = tr + r - sr, tc + c - sc
        if 0 <= y < h and 0 <= x < w:
            out[y][x] = color
    return out
